(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-632":{scenario:{company:"Vĩnh An Supervision Consultants",supervisor:{name:"Trần Văn Thắng",role:{vi:"Trưởng đoàn tư vấn giám sát",en:"Chief Site Supervisor"}},ref_code:"PP-0516",title:{vi:"Đủ cường độ mới tháo. Đủ mẫu mới nghiệm thu.",en:"Strip only at strength. Accept only with samples."},brief:{vi:"Bạn là kỹ sư giám sát, soát xét kế hoạch đổ bê tông và tháo cốp pha PP-0516 của nhà thầu cho sàn tầng 5. Khối đổ gồm bản sàn 40 m x 30 m dày 0,16 m và hệ dầm 30,6 m3; nhịp dầm lớn nhất 7,2 m. Bản nháp ghi tháo cốp pha chịu lực khi bê tông đạt 50% R28 và lấy mẫu theo quy tắc của móng khối lớn. Hãy sửa ngưỡng tháo cốp pha và số tổ mẫu thí nghiệm, rồi lập báo cáo có căn cứ.",en:"As the site supervision engineer, you are reviewing the contractor's pour and stripping plan PP-0516 for the level 5 slab. The pour covers a 40 m x 30 m slab, 0.16 m thick, plus 30.6 m3 of beams; the longest beam span is 7.2 m. The draft strips load-bearing formwork at 50% of R28 and samples by the mass-foundation rule. Correct the stripping threshold and the number of test sample sets, then write an evidence-based report."},reference_title:{vi:"Chỉ dẫn kỹ thuật bê tông & bảng khối lượng đã duyệt",en:"Approved concrete specification & pour quantities"},fields:[{id:"STRIP_LEVEL",label:{vi:"Cường độ tối thiểu để tháo cốp pha chịu lực",en:"Minimum strength to strip load-bearing formwork"},initial:"50%R28",expected:"70%R28",choices:["50%R28","70%R28","90%R28"],reference:"Bảng tháo cốp pha chịu lực",ref_value:{vi:"Phân theo khẩu độ: dưới 2 m, từ 2 m đến 8 m, trên 8 m; nhịp lớn nhất của khối đổ 7,2 m",en:"By span: under 2 m, 2 m to 8 m, over 8 m; longest span in the pour 7.2 m"},hint:{vi:"Tra bảng: khẩu độ dưới 2 m cần 50%, từ 2 đến 8 m cần 70%, trên 8 m cần 90% R28; xét theo nhịp lớn nhất.",en:"Look up: spans under 2 m need 50%, 2 to 8 m need 70%, over 8 m need 90% of R28; use the longest span."}},{id:"SAMPLE_SETS",label:{vi:"Số tổ mẫu nén bê tông cho khối đổ",en:"Compression sample sets for the pour"},initial:"3",expected:"12",reference:"Bảng khối lượng khối đổ sàn tầng 5",ref_value:{vi:"Bản sàn 40 x 30 x 0,16 m; dầm 30,6 m3; kết cấu khung, dầm, sàn",en:"Slab 40 x 30 x 0.16 m; beams 30.6 m3; frame, beam and slab structure"},hint:{vi:"Bản nháp áp quy tắc 100 m3 một tổ của móng khối lớn; dầm và sàn là kết cấu mỏng.",en:"The draft used the 100 m3 per set rule for mass foundations; beams and slabs are thin members."}}],sop32:{vi:"Khối lượng khối đổ = thể tích bản sàn + thể tích dầm. Kết cấu khung, dầm, sàn: cứ 20 m3 bê tông lấy 1 tổ mẫu (3 viên); phần lẻ chưa đủ 20 m3 vẫn lấy thêm 1 tổ.",en:"Pour volume = slab volume + beam volume. Frames, beams and slabs: 1 sample set (3 specimens) per 20 m3 of concrete; any remainder below 20 m3 still requires one more set."},context:{label:"NHẬT KÝ THI CÔNG / PP-0516",metrics:[{label:{vi:"Diện tích sàn",en:"Slab area"},value:"1,200 m2"},{label:{vi:"Nhịp dầm lớn nhất",en:"Longest beam span"},value:"7.2 m"},{label:{vi:"Cấp độ bền bê tông",en:"Concrete strength class"},value:"B30"}]},crisis:{vi:"Chỉ huy trưởng nhà thầu: “Ngày thứ 5 tháo hết cốp pha sàn để quay vòng lên tầng 6, chậm là bị phạt tiến độ. Lấy 3 tổ mẫu là đủ, em ký biên bản nghiệm thu luôn cho anh.”",en:"The contractor's site manager: “We strip all slab formwork on day 5 to cycle it to level 6, or we pay delay penalties. Three sample sets are enough, just sign the acceptance record for me.”"},options:{safe:{vi:"Không ký; yêu cầu lấy đủ tổ mẫu theo khối lượng, chỉ tháo cốp pha chịu lực khi kết quả nén đạt ngưỡng; báo trưởng đoàn giám sát, đề xuất thêm bộ cốp pha hoặc chống lại để giữ tiến độ.",en:"Refuse to sign; require full sampling for the volume and strip load-bearing formwork only when test results reach the threshold; inform the chief supervisor and propose extra formwork or reshoring."},shortcut:{vi:"Ký biên bản và cho tháo ngày thứ 5 vì trời nắng nóng, bê tông chắc đã đủ cường độ.",en:"Sign the record and allow stripping on day 5 because hot weather surely gave enough strength."},wait:{vi:"Không ký nhưng cũng không báo ai, để nhà thầu tự quyết định ngày tháo cốp pha.",en:"Do not sign but tell no one, leaving the contractor to choose the stripping day."}},questions:{vi:["Giải thích vì sao ngưỡng tháo cốp pha phải là 70% R28 và cách bạn tính số tổ mẫu từ khối lượng khối đổ.","Nếu nhà thầu tự ý tháo sớm, bạn xử lý hiện trường và hồ sơ như thế nào để kiểm soát rủi ro sập đổ?"],en:["Explain why the stripping threshold must be 70% of R28 and how you derived the sample sets from the pour volume.","If the contractor strips early on its own, how do you handle the site and the records to control collapse risk?"]},hints:{vi:["Đặt kế hoạch nháp cạnh bảng tháo cốp pha chịu lực và đối chiếu với nhịp dầm lớn nhất của khối đổ.","Theo SOP mục 3.2, tính đủ thể tích sàn và dầm rồi chia theo quy tắc lấy mẫu của kết cấu mỏng, phần lẻ làm tròn lên.","SOP mục 4.2: tiến độ không thay thế được kết quả thí nghiệm; áp lực ký nghiệm thu phải báo trưởng đoàn."],en:["Place the draft plan next to the stripping table and compare it with the longest beam span in the pour.","Under SOP 3.2, add the full slab and beam volumes, then divide by the thin-member sampling rule and round up.","SOP 4.2: schedule never replaces test results; escalate any pressure to sign acceptance to the chief supervisor."]}},learning:{summary:{vi:"Kỹ sư giám sát thi công công trình dân dụng và công nghiệp kiểm soát chất lượng, khối lượng, tiến độ và an toàn tại hiện trường, bảo đảm công trình được thi công đúng thiết kế, chỉ dẫn kỹ thuật và quy chuẩn. Họ kiểm tra vật liệu đầu vào, nghiệm thu từng công việc, giám sát biện pháp thi công và lập hồ sơ quản lý chất lượng. Nghề cần kiến thức kết cấu, công nghệ thi công, kỹ năng phối hợp và bản lĩnh nói không với làm tắt.",en:"A site construction engineer for civil and industrial buildings controls quality, quantities, schedule and safety on site, making sure works follow the design, specifications and codes. They inspect incoming materials, accept each work stage, supervise construction methods and keep the quality records. The role needs structural and construction technology knowledge, coordination skills and the firmness to say no to shortcuts."},responsibilities:{vi:["Kiểm tra điều kiện khởi công, biện pháp thi công và kế hoạch kiểm soát chất lượng của nhà thầu.","Kiểm tra vật liệu, cấu kiện đầu vào, chứng chỉ xuất xưởng và kết quả thí nghiệm.","Giám sát và nghiệm thu từng công việc: cốp pha, cốt thép, bê tông, hoàn thiện.","Theo dõi an toàn lao động, vệ sinh môi trường và yêu cầu dừng thi công khi có nguy cơ mất an toàn.","Ghi nhật ký giám sát, lập báo cáo định kỳ và hoàn thiện hồ sơ hoàn công."],en:["Check start-up conditions, method statements and the contractor's quality control plan.","Inspect incoming materials and components, mill certificates and test results.","Supervise and accept each work stage: formwork, rebar, concrete and finishes.","Monitor safety and environment and order work to stop when there is an unsafe condition.","Keep the supervision log, issue periodic reports and complete as-built records."]},competencies:[{name:{vi:"Đọc và đối chiếu bản vẽ",en:"Drawing review"},desc:{vi:"Phát hiện sai khác giữa bản vẽ thi công, shop drawing và thực tế hiện trường.",en:"Spot differences between construction drawings, shop drawings and actual site conditions."}},{name:{vi:"Công nghệ bê tông",en:"Concrete technology"},desc:{vi:"Kiểm soát cấp phối, độ sụt, đổ, đầm, bảo dưỡng, lấy mẫu và thời điểm tháo cốp pha.",en:"Control mix design, slump, placing, compaction, curing, sampling and stripping time."}},{name:{vi:"Nghiệm thu & hồ sơ chất lượng",en:"Acceptance & quality records"},desc:{vi:"Lập biên bản, nhật ký và hồ sơ đủ căn cứ pháp lý cho từng giai đoạn.",en:"Prepare acceptance records, logs and files with full legal evidence for each stage."}},{name:{vi:"An toàn thi công",en:"Construction safety"},desc:{vi:"Nhận diện rủi ro sập đổ, ngã cao, điện và yêu cầu biện pháp khắc phục kịp thời.",en:"Identify collapse, fall and electrical risks and demand timely corrective measures."}},{name:{vi:"Bản lĩnh nghề nghiệp",en:"Professional firmness"},desc:{vi:"Giữ nguyên tắc kỹ thuật dưới áp lực tiến độ, báo cáo trung thực với chủ đầu tư.",en:"Hold technical principles under schedule pressure and report honestly to the client."}}],knowledge:{vi:["Nghị định 06/2021/NĐ-CP về quản lý chất lượng, thi công xây dựng và bảo trì công trình.","TCVN 4453:1995 - Kết cấu bê tông và bê tông cốt thép toàn khối: quy phạm thi công và nghiệm thu.","TCVN 5574:2018 - Thiết kế kết cấu bê tông và bê tông cốt thép, cấp độ bền chịu nén B.","Quy định hiện hành về an toàn lao động trong thi công xây dựng, giàn giáo và cốp pha.","Nguyên tắc lấy mẫu, bảo dưỡng và thí nghiệm nén mẫu bê tông theo tiêu chuẩn quốc gia."],en:["Decree 06/2021/ND-CP on quality management, construction and maintenance of works.","TCVN 4453:1995 - Monolithic concrete and reinforced concrete structures: code for construction and acceptance.","TCVN 5574:2018 - Design of concrete and reinforced concrete structures, compressive strength classes B.","Current regulations on occupational safety in construction, scaffolding and formwork.","Principles of sampling, curing and compression testing of concrete under national standards."]},tools:["Máy toàn đạc điện tử","Máy thủy bình","Súng bật nẩy kiểm tra bê tông","Côn đo độ sụt (côn Abrams)","Ứng dụng nhật ký công trình điện tử"],kpis:{vi:["Tỷ lệ công việc nghiệm thu đạt ngay lần đầu.","Số sự cố an toàn, chất lượng nghiêm trọng (mục tiêu bằng 0).","Tỷ lệ hồ sơ chất lượng hoàn thiện đồng bộ với tiến độ thi công.","Thời gian phản hồi yêu cầu nghiệm thu của nhà thầu."],en:["Share of work stages accepted first time.","Serious safety or quality incidents (target zero).","Share of quality records completed in step with construction progress.","Response time to contractor inspection requests."]},day:[{time:"07:00",vi:"Kiểm tra hiện trường đầu ca: giàn giáo, cốp pha, lan can an toàn, điện thi công.",en:"Walk the site at shift start: scaffolding, formwork, guardrails and temporary power."},{time:"08:30",vi:"Nghiệm thu cốt thép sàn tầng 5: đường kính, khoảng cách, lớp bê tông bảo vệ, nối buộc.",en:"Inspect level 5 slab rebar: diameter, spacing, cover and laps."},{time:"10:30",vi:"Kiểm tra phiếu giao bê tông, đo độ sụt, giám sát đổ, đầm và lấy mẫu.",en:"Check delivery tickets, test slump and supervise placing, compaction and sampling."},{time:"14:00",vi:"Họp giao ban với nhà thầu và chủ đầu tư về tiến độ, chất lượng, biện pháp tháo cốp pha.",en:"Hold the site meeting with contractor and client on schedule, quality and stripping method."},{time:"16:30",vi:"Ghi nhật ký giám sát, cập nhật hồ sơ chất lượng và báo cáo ngày.",en:"Write the supervision log, update quality records and the daily report."}],mistakes:{vi:["Cho tháo cốp pha chịu lực theo số ngày mà không có kết quả nén mẫu đạt ngưỡng.","Lấy thiếu tổ mẫu do áp quy tắc của móng khối lớn cho dầm, sàn.","Ký biên bản nghiệm thu trước khi kiểm tra thực tế hiện trường."],en:["Allowing load-bearing formwork removal by day count without test results at the threshold.","Taking too few sample sets by applying the mass-foundation rule to beams and slabs.","Signing acceptance records before inspecting the actual work on site."]},career:[{vi:"Kỹ thuật viên giám sát hiện trường",en:"Site inspection technician"},{vi:"Kỹ sư giám sát thi công",en:"Site supervision engineer"},{vi:"Giám sát trưởng hạng mục",en:"Lead supervisor for a work package"},{vi:"Trưởng đoàn tư vấn giám sát",en:"Chief supervision consultant"}],glossary:[{term:"R28",vi:"Cường độ chịu nén của bê tông ở tuổi 28 ngày, mốc để đánh giá cấp độ bền.",en:"Concrete compressive strength at 28 days, the benchmark for its strength class."},{term:"Tổ mẫu",vi:"Nhóm 3 viên mẫu bê tông lấy cùng lúc, cùng chỗ để thí nghiệm nén.",en:"A group of 3 concrete specimens taken together at the same location for compression testing."},{term:"Độ sụt",vi:"Chỉ tiêu tính công tác của hỗn hợp bê tông tươi, đo bằng côn tiêu chuẩn.",en:"Workability measure of fresh concrete, tested with the standard cone."},{term:"Reshoring",vi:"Chống lại tạm thời sau khi tháo cốp pha để kết cấu non tuổi không chịu tải vượt khả năng.",en:"Temporary re-propping after stripping so young concrete is not loaded beyond its capacity."},{term:"Shop drawing",vi:"Bản vẽ triển khai thi công chi tiết do nhà thầu lập trên cơ sở thiết kế đã duyệt.",en:"Detailed construction drawing prepared by the contractor from the approved design."}],quiz:[{q:{vi:"Khối đổ gồm sàn 90 m3 và dầm 25 m3 (kết cấu mỏng, 20 m3 một tổ, phần lẻ thêm 1 tổ). Cần bao nhiêu tổ mẫu?",en:"A pour has 90 m3 of slab and 25 m3 of beams (thin members, one set per 20 m3, remainder adds a set). How many sample sets?"},options:{vi:["5 tổ","6 tổ","2 tổ","12 tổ"],en:["5 sets","6 sets","2 sets","12 sets"]},answer:1,explain:{vi:"Tổng 115 m3 / 20 = 5,75, làm tròn lên thành 6 tổ mẫu.",en:"Total 115 m3 / 20 = 5.75, rounded up to 6 sample sets."}},{q:{vi:"Cốp pha đáy dầm khẩu độ 9 m chỉ được tháo khi bê tông đạt tối thiểu bao nhiêu phần trăm R28?",en:"Bottom formwork of a 9 m span beam may be stripped only when concrete reaches at least what percentage of R28?"},options:{vi:["50%","70%","100%","90%"],en:["50%","70%","100%","90%"]},answer:3,explain:{vi:"Bản, dầm khẩu độ trên 8 m cần đạt tối thiểu 90% R28 trước khi tháo cốp pha chịu lực.",en:"Slabs and beams spanning over 8 m need at least 90% of R28 before load-bearing formwork is removed."}},{q:{vi:"Nhà thầu muốn tháo cốp pha sớm để kịp tiến độ khi chưa có kết quả nén mẫu. Bạn làm gì?",en:"The contractor wants to strip formwork early for schedule before any test results exist. What do you do?"},options:{vi:["Không chấp thuận, yêu cầu kết quả thí nghiệm, báo trưởng đoàn và đề xuất chống lại hoặc thêm cốp pha","Đồng ý nếu thời tiết nắng nóng","Cho tháo một nửa sàn","Không ý kiến để nhà thầu tự chịu trách nhiệm"],en:["Refuse, require test results, inform the chief and propose reshoring or extra formwork","Agree if the weather is hot","Allow half the slab to be stripped","Say nothing and let the contractor take responsibility"]},answer:0,explain:{vi:"Tháo cốp pha khi chưa đủ cường độ có thể gây sập; giám sát phải dựa vào kết quả thí nghiệm và đề xuất giải pháp tiến độ an toàn.",en:"Stripping before strength is reached can cause collapse; supervision must rely on test results and offer safe schedule options."}},{q:{vi:"Độ sụt của hỗn hợp bê tông dùng để đánh giá đặc tính nào?",en:"What property does the slump of fresh concrete assess?"},options:{vi:["Cường độ chịu nén","Khả năng chống thấm","Tính công tác của hỗn hợp bê tông","Mô đun đàn hồi"],en:["Compressive strength","Water tightness","Workability of the fresh mix","Elastic modulus"]},answer:2,explain:{vi:"Độ sụt phản ánh tính công tác, ảnh hưởng đến việc đổ, đầm; nó không đo trực tiếp cường độ.",en:"Slump reflects workability, which affects placing and compaction; it does not measure strength directly."}}],tools_en:["Total station","Automatic level","Rebound hammer for concrete testing","Slump cone (Abrams cone)","Electronic site diary app"]}}})})(window.KKR);
